css:
.device-case {
  --case: #e6e6e2;
  --text-dark: #2a2a2a;
  --accent-orange: #f04e30;
  --accent-green: #4a6fa5;
  --grid-lines: #c0c0bc;

  width: 360px;
  height: 450px;
  background-color: var(--case);
  border-radius: 12px;
  font-family: "Inter", sans-serif;
  box-shadow:
    15px 15px 30px rgba(0, 0, 0, 0.1),
    -5px -5px 15px rgba(255, 255, 255, 0.8);
  padding: 25px;
  display: flex;
  flex-direction: column;
  position: relative;
}

.inputs {
  display: none;
}

.speaker-grille {
  width: 100%;
  height: 50px;
  background-image: radial-gradient(#aaa 1.5px, transparent 1.5px);
  background-size: 6px 6px;
  margin-bottom: 15px;
  opacity: 0.6;
}

.screen-window {
  width: 100%;
  height: 270px;
  background: #f0f0f0;
  border: 1px solid #d0d0d0;
  border-radius: 4px;
  position: relative;
  overflow: hidden;
  box-shadow: inset 2px 2px 5px rgba(0, 0, 0, 0.05);
  margin-bottom: 10px;
}

.glass-glare {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    120deg,
    rgba(255, 255, 255, 0) 40%,
    rgba(255, 255, 255, 0.4) 50%,
    rgba(255, 255, 255, 0) 60%
  );
  z-index: 10;
  pointer-events: none;
}

.tuner-band {
  display: flex;
  width: 400%;
  height: 100%;
  transition: transform 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.panel {
  width: 25%;
  height: 100%;
  padding: 20px;
  position: relative;
  border-right: 1px solid var(--grid-lines);
  background: linear-gradient(90deg, transparent 95%, var(--grid-lines) 95%),
    linear-gradient(transparent 95%, var(--grid-lines) 95%);
  background-size: 20px 20px;
}

.label {
  font-weight: 800;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 10px;
  color: #666;
}

.freq-display {
  position: absolute;
  bottom: 20px;
  left: 0;
  width: 100%;
  height: 40px;
  border-top: 2px solid var(--text-dark);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  font-family: monospace;
  font-size: 0.9rem;
}

.freq-needle {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 2px;
  height: 100%;
  background: var(--accent-orange);
  z-index: 5;
}

.tape-mechanism {
  display: flex;
  justify-content: center;
  gap: 30px;
  margin-top: 40px;
}

.spool {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: #ddd;
  position: relative;
  border: 1px solid #bbb;
  overflow: hidden;
}

.spool::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: conic-gradient(
    #333 0deg,
    #333 120deg,
    transparent 120deg,
    transparent 180deg,
    #333 180deg,
    #333 300deg,
    transparent 300deg
  );
  border-radius: 50%;
}

.counter-box {
  background: #222;
  color: #fff;
  padding: 5px 10px;
  font-family: monospace;
  border-radius: 2px;
  display: inline-block;
  letter-spacing: 4px;
  margin-top: 20px;
}

.waveform {
  width: 100%;
  height: 80px;
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: 20px;
}

.wave-bar {
  flex: 1;
  background: var(--text-dark);
  height: 10px;
  animation: equalize 1s ease-in-out infinite;
}

@keyframes equalize {
  0%,
  100% {
    height: 10px;
  }
  50% {
    height: 60px;
  }
}

.switch-row {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-top: 20px;
}

.toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.9rem;
  font-weight: 600;
}

.toggle-graphic {
  width: 40px;
  height: 20px;
  background: #ccc;
  border-radius: 10px;
  position: relative;
}
.toggle-graphic::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.controls-strip {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 5px;
  margin-bottom: 10px;
}

.push-btn {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: #f5f5f5;
  border: 1px solid #ddd;
  box-shadow:
    inset 0 0 5px rgba(255, 255, 255, 1),
    3px 3px 6px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.1s;
  position: relative;
}

.push-btn::after {
  content: "";
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #e0e0e0;
  box-shadow: inset 1px 1px 2px rgba(0, 0, 0, 0.1);
}

.push-btn:active {
  box-shadow:
    inset 2px 2px 5px rgba(0, 0, 0, 0.1),
    1px 1px 2px rgba(0, 0, 0, 0.1);
  transform: translateY(1px);
}

.push-btn:active::after {
  background: var(--accent-orange);
}

.btn-label {
  position: absolute;
  bottom: -25px;
  font-size: 0.65rem;
  font-weight: 600;
  color: #888;
  text-transform: uppercase;
}

#app1:checked ~ .screen-window .tuner-band {
  transform: translateX(0%);
}
#app2:checked ~ .screen-window .tuner-band {
  transform: translateX(-25%);
}
#app3:checked ~ .screen-window .tuner-band {
  transform: translateX(-50%);
}
#app4:checked ~ .screen-window .tuner-band {
  transform: translateX(-75%);
}

#app1:checked ~ .controls-strip label[for="app1"]::after {
  background: var(--accent-green);
}
#app2:checked ~ .controls-strip label[for="app2"]::after {
  background: var(--accent-green);
}
#app3:checked ~ .controls-strip label[for="app3"]::after {
  background: var(--accent-green);
}
#app4:checked ~ .controls-strip label[for="app4"]::after {
  background: var(--accent-green);
}

#app1:checked ~ .screen-window .tuner-band .panel-1 .tape-mechanism .spool {
  animation: spin 4s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
